import{_ as e,d as a,e as d,y as r}from"./chunks/framework.D7CAgLCq.js";const f=JSON.parse('{"title":"地位已经成立，为什么效果仍可能没有发生","description":"构成条件、当事人理解、实际兑现和规范正当性，可能各有不同答案。","frontmatter":{"title":"地位已经成立，为什么效果仍可能没有发生","description":"构成条件、当事人理解、实际兑现和规范正当性，可能各有不同答案。"},"headers":[],"relativePath":"concepts/status-and-effects.md","filePath":"concepts/status-and-effects.md"}'),s={name:"concepts/status-and-effects.md"};function o(n,t,p,c,h,i){return a(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="地位已经成立-为什么效果仍可能没有发生" tabindex="-1">地位已经成立，为什么效果仍可能没有发生 <a class="header-anchor" href="#地位已经成立-为什么效果仍可能没有发生" aria-label="Permalink to &quot;地位已经成立，为什么效果仍可能没有发生&quot;">​</a></h1><p>构成条件、当事人理解、实际兑现和规范正当性，可能各有不同答案。</p><p>一项服务资格已经有效授予，服务却迟迟没有到达。能否说资格没有成立？也能否只凭资格就说人已经得到帮助？两种推断都跳过了一个独立问题。</p><p><a href="./../theory/part-02.html#section-2-4-3">§2.4.3</a>把<strong>构成关系</strong>与<strong>因果关系</strong>分开。构成问题核规则来源、有权主体、要求的形式和个案适用；因果问题核地位成立后经什么通道改变实际结果。</p><div class="xk-table"><table><thead><tr><th>问题</th><th>所需材料</th><th>不能代证什么</th></tr></thead><tbody><tr><td>地位是否成立</td><td>适用规则、有效文书、权限与形式</td><td>实际履行与效果</td></tr><tr><td>当事人如何理解</td><td>具体表达、语境和理解材料</td><td>有效授权或真正同意</td></tr><tr><td>是否兑现及有何作用</td><td>实施记录、结果与因果比较</td><td>法律有效或规范正当</td></tr><tr><td>安排是否正当</td><td>公开规范理由、保护与受影响位置</td><td>事实已经发生</td></tr></tbody></table></div><p>教学情景：会员资格已依有效规则取得，系统却未开放访问。可以确认资格并记录执行缺口；若某个没有资格的人误获访问，访问事实也不能自动补造资格。现实个案须回到其具体法源与程序。</p><p>这一分工不宣称所有对象都由约定产生。它也使G1的范围更清楚：可靠记录可以支持成员和机构事实，采用这些分组是否增加预测能力另由比较判断。</p><p>继续阅读：<a href="./../theory/part-05.html#section-5-5-5">§5.5.5制度层级</a>、<a href="./../theory/part-14.html#section-14-6">§14.6授权</a>、<a href="./../theory/appendix-d/d-21.html#section-d-21">D.21法律与责任</a>。</p>',8)])])}const _=e(s,[["render",o]]);export{f as __pageData,_ as default};
